import React, { useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { X, User, ChevronUp } from 'lucide-react';
import styles from './ProfileDrawer.module.css';

export default function ProfileDrawer({ isOpen, onClose }) {
  const { user, logout } = useAuth();
  const navigate = useNavigate();

  // Prevent background scroll when drawer is open
  useEffect(() => {
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => {
      document.body.style.overflow = '';
    };
  }, [isOpen]);

  if (!isOpen || !user) return null;

  const handleLogout = () => {
    logout();
    onClose();
    navigate('/');
  };

  const handleNav = (path) => {
    onClose();
    navigate(path);
  };

  return (
    <div className={styles.overlay} onClick={onClose}>
      <aside
        className={styles.drawer}
        onClick={(e) => e.stopPropagation()}
        role="dialog"
        aria-modal="true"
        aria-label="User Profile"
      >
        {/* Header */}
        <div className={styles.header}>
          <h2 className={styles.title}>Profile</h2>
          <button
            type="button"
            className={styles.closeBtn}
            onClick={onClose}
            aria-label="Close Profile"
          >
            <X size={20} />
          </button>
        </div>

        {/* Body */}
        <div className={styles.body}>
          {/* User Card matching PropTiger reference */}
          <div className={styles.userCard}>
            <div className={styles.avatarCircle}>
              {user.photo ? (
                <img src={user.photo} alt={user.name} className={styles.avatarImg} />
              ) : (
                <User size={28} />
              )}
            </div>
            <div className={styles.userInfo}>
              <div className={styles.greeting} title={user.name || user.email}>
                Hi {user.name || user.email}
              </div>
              <div className={styles.userPhone}>
                {user.phone ? user.phone : user.email}
              </div>
            </div>
          </div>

          {/* Menu Items matching reference image */}
          <nav className={styles.menuList}>
            <button
              type="button"
              className={styles.menuItem}
              onClick={() => handleNav('/search')}
            >
              <span>Recently viewed projects</span>
              <ChevronUp size={16} className={styles.chevron} />
            </button>

            <button
              type="button"
              className={styles.menuItem}
              onClick={() => handleNav('/account?tab=enquiries')}
            >
              <span>Enquired Properties</span>
              <ChevronUp size={16} className={styles.chevron} />
            </button>

            <button
              type="button"
              className={styles.menuItem}
              onClick={() => handleNav('/saved')}
            >
              <span>Liked Properties</span>
              <ChevronUp size={16} className={styles.chevron} />
            </button>

            <button
              type="button"
              className={styles.menuItem}
              onClick={() => handleNav('/account?tab=visits')}
            >
              <span>Site Visit</span>
              <ChevronUp size={16} className={styles.chevron} />
            </button>

            <button
              type="button"
              className={styles.menuItem}
              onClick={() => handleNav('/account?tab=listings')}
            >
              <span>My Bookings</span>
              <ChevronUp size={16} className={styles.chevron} />
            </button>

            <button
              type="button"
              className={styles.logoutItem}
              onClick={handleLogout}
            >
              <span>Logout</span>
            </button>
          </nav>

          <div className={styles.footerNote}>
            ProBridge Real Estate Network • Verified Listings
          </div>
        </div>
      </aside>
    </div>
  );
}
